$n=0;function assert3(bool $ok,string $label): void {global $n;if(!$ok)throw new RuntimeException($label);$n++;echo "PASS $label\n";}
function rejects(callable $fn,string $label): void {try{$fn();$bad=false;}catch(AppError $e){$bad=true;}assert3($bad,$label);}
assert3(decimal_kwh('0.100000')['micro']===100000,'exact micro-kWh');assert3(decimal_kwh('42.6800')['raw']==='42.6800','raw precision preserved');assert3(decimal_kwh('42.6800')['exact']==='42.680000','decimal database value');
