$up=analyse_reading($prev,$rows,[],$fc,['balance'=>100.],$now+3600,$o);assert3($up['interval']===null&&$up['analysis']['samples']===4&&!$up['analysis']['provisional'],'ambiguous recharge preserves load history');assert3($up['analysis']['recharge_class']==='ambiguous','recharge evidence separated');
