$same=analyse_reading($prev,$rows,[],$fc,['balance'=>74.4],$now+4*3600,$o);assert3($same['interval']===null&&$same['analysis']['freshness']==='stale','unknown repeated balance not zero evidence');assert3($same['analysis']['forecast_run']['origin']==$fc['forecast_run']['origin'],'cached balance does not refresh origin');
$p=['ts'=>$now+4*3600,'balance'=>74.4,'meter_ts'=>null,'analysis'=>json_value($same['analysis'])];$batch=analyse_reading($p,$rows,[],$fc,['balance'=>70.4],$now+5*3600,$o);assert3($batch['interval']['usable']===1&&$batch['analysis']['interval_use']==='aggregate_only','batch total supplied to slow expert');assert3(abs($batch['interval']['hours']-5)<1e-9,'batch uses full plateau interval');
$gap=analyse_reading($prev,$rows,[],$fc,['balance'=>40.],$now+48*3600,$o);assert3($gap['analysis']['interval_use']==='aggregate_only','long total slow-only');
$freshPrev=$prev;$freshPrev['meter_ts']=$now;$zero=analyse_reading($freshPrev,$rows,[],$fc,['balance'=>74.4,'meter_ts'=>$now+8*3600,'freshness_confirmed'=>true],$now+8*3600,$o);assert3($zero['interval']['tag']==='fresh_zero'&&$zero['interval']['energy_lower']===0.&&$zero['interval']['energy_upper']>0.,'fresh unchanged interval has quantization bounds, not exact zero');assert3($zero['analysis']['rate']<$fc['rate'],'fresh zero lowers load');
