$run=$fc['forecast_run'];$lastMean=0.;$lastUpper=0.;$monotone=true;foreach($run['points'] as $point){if($point['mean']<$lastMean||$point['upper']<$lastUpper)$monotone=false;$lastMean=$point['mean'];$lastUpper=$point['upper'];}assert3($monotone&&count($run['points'])===289,'nonnegative coherent 15-minute path');assert3(ts_crossing($run,10000.,3.,true)===null,'horizon exceed null, no 72.01 sentinel');assert3(ts_crossing($run,2.,3.,true)===0.,'already below line time zero');
assert3(ts_quantile([1.,2.,3.],.99)===null,'insufficient order statistic no fabricated tail');$learn=ts_learning();$scored=ts_score($learn,$run,4.8,6.,$now+21600,'block1');assert3($scored['scores']['ew6'][0]['count']===1,'saved expert scored before refit');assert3(ts_score($scored,$run,4.8,6.,$now+21600,'block1')===$scored,'validation block idempotence');
